const mergeTranslationPatch = (target, patch) => {
  Object.entries(patch).forEach(([key, value]) => {
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      target[key] = mergeTranslationPatch(target[key] || {}, value);
    } else {
      target[key] = value;
    }
  });
  return target;
};

